window.WORD_COURSE={"id":"bnu6a-word-20261021","chapters":[{"id":1,"title":"分数除法","count":13},{"id":2,"title":"圆","count":14}],"groups":[{"id":"f01","c":1,"title":"平均分，求每份量","method":"总量÷份数","pages":"2—3","trap":"平均分成3份，是乘1/3，不是减去3。","items":[{"text":"有3/4米彩带，平均分成3份，每份有多少米？","given":["总量：3/4米","平均分成：3份"],"want":"每份的彩带有多少米","relation":"每份量 × 份数 = 总量","formula":"3/4 ÷ 3","steps":["求平均每一份，用总量除以份数。","3/4÷3=3/4×1/3=1/4。","检验：1/4×3=3/4。"],"answer":"1/4","answerText":"1/4","unit":"米","model":{"type":"share","a":3,"b":4,"n":3},"ask":["题目是在求每份量，还是求份数？","平均分成几份，每份是总量的几分之一？"],"change":"先学会这一组的分析方法","id":"f01-0","level":"讲解例题"},{"text":"有4/5米彩带，平均分成2份，每份有多少米？","given":["总量：4/5米","平均分成：2份"],"want":"每份的彩带有多少米","relation":"每份量 × 份数 = 总量","formula":"4/5 ÷ 2","steps":["求平均每一份，用总量除以份数。","4/5÷2=4/5×1/2=2/5。","检验：2/5×2=4/5。"],"answer":"2/5","answerText":"2/5","unit":"米","model":{"type":"share","a":4,"b":5,"n":2},"ask":["题目是在求每份量，还是求份数？","平均分成几份，每份是总量的几分之一？"],"change":"更换数据，数量关系不变","id":"f01-1","level":"基础变式"},{"text":"有5/6升果汁，平均分成5份，每份有多少升？","given":["总量：5/6升","平均分成：5份"],"want":"每份的果汁有多少升","relation":"每份量 × 份数 = 总量","formula":"5/6 ÷ 5","steps":["求平均每一份，用总量除以份数。","5/6÷5=5/6×1/5=1/6。","检验：1/6×5=5/6。"],"answer":"1/6","answerText":"1/6","unit":"升","model":{"type":"share","a":5,"b":6,"n":5},"ask":["题目是在求每份量，还是求份数？","平均分成几份，每份是总量的几分之一？"],"change":"更换情境或问法，仍从同一关系出发","id":"f01-2","level":"情境变式"},{"text":"有7/8米丝带，平均分成6份，每份有多少米？","given":["总量：7/8米","平均分成：6份"],"want":"每份的丝带有多少米","relation":"每份量 × 份数 = 总量","formula":"7/8 ÷ 6","steps":["求平均每一份，用总量除以份数。","7/8÷6=7/8×1/6=7/48。","检验：7/48×6=7/8。"],"answer":"7/48","answerText":"7/48","unit":"米","model":{"type":"share","a":7,"b":8,"n":6},"ask":["题目是在求每份量，还是求份数？","平均分成几份，每份是总量的几分之一？"],"change":"增加条件、逆向设问或提高计算要求","id":"f01-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"f02","c":1,"title":"求能分成几份","method":"总量÷每份量","pages":"4—6","trap":"看清“每份多大”和“有几份”，不是看到分数就乘。","items":[{"text":"有3/4米绳子，每份取1/8米，一共能分成多少份？","given":["总量：3/4米","每份：1/8米"],"want":"能分成多少份","relation":"份数 × 每份量 = 总量","formula":"3/4 ÷ 1/8","steps":["求总量里包含多少个1/8，用总量除以每份量。","3/4÷1/8=6。","检验：6×1/8=3/4。"],"answer":"6","answerText":"6","unit":"份","model":{"type":"groups","total":"3/4","each":"1/8"},"ask":["每份量是多少？","题目要求每份多少，还是一共有几份？"],"change":"先学会这一组的分析方法","id":"f02-0","level":"讲解例题"},{"text":"有2米彩带，每份取1/3米，一共能分成多少份？","given":["总量：2米","每份：1/3米"],"want":"能分成多少份","relation":"份数 × 每份量 = 总量","formula":"2 ÷ 1/3","steps":["求总量里包含多少个1/3，用总量除以每份量。","2÷1/3=6。","检验：6×1/3=2。"],"answer":"6","answerText":"6","unit":"份","model":{"type":"groups","total":"2","each":"1/3"},"ask":["每份量是多少？","题目要求每份多少，还是一共有几份？"],"change":"更换数据，数量关系不变","id":"f02-1","level":"基础变式"},{"text":"有3/5升饮料，每份取1/10升，一共能分成多少份？","given":["总量：3/5升","每份：1/10升"],"want":"能分成多少份","relation":"份数 × 每份量 = 总量","formula":"3/5 ÷ 1/10","steps":["求总量里包含多少个1/10，用总量除以每份量。","3/5÷1/10=6。","检验：6×1/10=3/5。"],"answer":"6","answerText":"6","unit":"份","model":{"type":"groups","total":"3/5","each":"1/10"},"ask":["每份量是多少？","题目要求每份多少，还是一共有几份？"],"change":"更换情境或问法，仍从同一关系出发","id":"f02-2","level":"情境变式"},{"text":"有9/5千克面粉，每份取3/10千克，一共能分成多少份？","given":["总量：9/5千克","每份：3/10千克"],"want":"能分成多少份","relation":"份数 × 每份量 = 总量","formula":"9/5 ÷ 3/10","steps":["求总量里包含多少个3/10，用总量除以每份量。","9/5÷3/10=6。","检验：6×3/10=9/5。"],"answer":"6","answerText":"6","unit":"份","model":{"type":"groups","total":"9/5","each":"3/10"},"ask":["每份量是多少？","题目要求每份多少，还是一共有几份？"],"change":"增加条件、逆向设问或提高计算要求","id":"f02-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"f03","c":1,"title":"已知整体，求其中一部分","method":"整体×对应分数","pages":"7—9（乘除对比）","trap":"与下一组使用相同数据，只交换已知量和问题。","items":[{"text":"有32本图书，其中3/8是科普类，科普类有多少本？","given":["总量：32本","所求部分占：3/8"],"want":"求其中这一部分","relation":"整体 × 对应分数 = 部分量","formula":"32 × 3/8","steps":["把全部图书看成单位“1”，整体已经知道。","求它的3/8，用乘法：32×3/8=12。","这12本是整体中的一部分，应小于32本。"],"answer":"12","answerText":"12","unit":"本","model":{"type":"fraction","mode":"part","total":"32","part":"12","rest":"20","k":3,"n":8,"unit":"本"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"先学会这一组的分析方法","id":"f03-0","level":"讲解例题"},{"text":"有45本图书，其中2/5是科普类，科普类有多少本？","given":["总量：45本","所求部分占：2/5"],"want":"求其中这一部分","relation":"整体 × 对应分数 = 部分量","formula":"45 × 2/5","steps":["把全部图书看成单位“1”，整体已经知道。","求它的2/5，用乘法：45×2/5=18。","这18本是整体中的一部分，应小于45本。"],"answer":"18","answerText":"18","unit":"本","model":{"type":"fraction","mode":"part","total":"45","part":"18","rest":"27","k":2,"n":5,"unit":"本"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"更换数据，数量关系不变","id":"f03-1","level":"基础变式"},{"text":"有36张彩纸，其中5/6是红色，红色有多少张？","given":["总量：36张","所求部分占：5/6"],"want":"求其中这一部分","relation":"整体 × 对应分数 = 部分量","formula":"36 × 5/6","steps":["把全部彩纸看成单位“1”，整体已经知道。","求它的5/6，用乘法：36×5/6=30。","这30张是整体中的一部分，应小于36张。"],"answer":"30","answerText":"30","unit":"张","model":{"type":"fraction","mode":"part","total":"36","part":"30","rest":"6","k":5,"n":6,"unit":"张"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"更换情境或问法，仍从同一关系出发","id":"f03-2","level":"情境变式"},{"text":"有56张卡片，其中3/7是红色，红色有多少张？","given":["总量：56张","所求部分占：3/7"],"want":"求其中这一部分","relation":"整体 × 对应分数 = 部分量","formula":"56 × 3/7","steps":["把全部卡片看成单位“1”，整体已经知道。","求它的3/7，用乘法：56×3/7=24。","这24张是整体中的一部分，应小于56张。"],"answer":"24","answerText":"24","unit":"张","model":{"type":"fraction","mode":"part","total":"56","part":"24","rest":"32","k":3,"n":7,"unit":"张"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"增加条件、逆向设问或提高计算要求","id":"f03-3","level":"进阶变式"}],"priority":true,"extension":false},{"id":"f04","c":1,"title":"已知部分，求整体","method":"部分量÷对应分数","pages":"7—9","trap":"部分量和分数必须对应。","items":[{"text":"图书中有12本科普类，占总量的3/8，一共有多少本图书？","given":["部分量：12本","这部分占：3/8"],"want":"求全部的量","relation":"整体 × 对应分数 = 部分量","formula":"12 ÷ 3/8","steps":["单位“1”是全部图书，这是未知量。","3份对应12本，1份是12÷3=4本。","8份是4×8=32本。","也可直接算：12÷3/8=32。"],"answer":"32","answerText":"32","unit":"本","model":{"type":"fraction","mode":"whole","total":"32","part":"12","rest":"20","k":3,"n":8,"unit":"本"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"先学会这一组的分析方法","id":"f04-0","level":"讲解例题"},{"text":"图书中有18本科普类，占总量的2/5，一共有多少本图书？","given":["部分量：18本","这部分占：2/5"],"want":"求全部的量","relation":"整体 × 对应分数 = 部分量","formula":"18 ÷ 2/5","steps":["单位“1”是全部图书，这是未知量。","2份对应18本，1份是18÷2=9本。","5份是9×5=45本。","也可直接算：18÷2/5=45。"],"answer":"45","answerText":"45","unit":"本","model":{"type":"fraction","mode":"whole","total":"45","part":"18","rest":"27","k":2,"n":5,"unit":"本"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"更换数据，数量关系不变","id":"f04-1","level":"基础变式"},{"text":"彩纸中有30张红色，占总量的5/6，一共有多少张彩纸？","given":["部分量：30张","这部分占：5/6"],"want":"求全部的量","relation":"整体 × 对应分数 = 部分量","formula":"30 ÷ 5/6","steps":["单位“1”是全部彩纸，这是未知量。","5份对应30张，1份是30÷5=6张。","6份是6×6=36张。","也可直接算：30÷5/6=36。"],"answer":"36","answerText":"36","unit":"张","model":{"type":"fraction","mode":"whole","total":"36","part":"30","rest":"6","k":5,"n":6,"unit":"张"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"更换情境或问法，仍从同一关系出发","id":"f04-2","level":"情境变式"},{"text":"卡片中有24张红色，占总量的3/7，一共有多少张卡片？","given":["部分量：24张","这部分占：3/7"],"want":"求全部的量","relation":"整体 × 对应分数 = 部分量","formula":"24 ÷ 3/7","steps":["单位“1”是全部卡片，这是未知量。","3份对应24张，1份是24÷3=8张。","7份是8×7=56张。","也可直接算：24÷3/7=56。"],"answer":"56","answerText":"56","unit":"张","model":{"type":"fraction","mode":"whole","total":"56","part":"24","rest":"32","k":3,"n":7,"unit":"张"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"增加条件、逆向设问或提高计算要求","id":"f04-3","level":"进阶变式"}],"priority":true,"extension":false},{"id":"f05","c":1,"title":"已知剩余，求原来的量","method":"剩余量÷剩余分数","pages":"7—10的对应关系变式","trap":"剩余量不能直接除以用去的分数。","items":[{"text":"一批彩带用去了2/5，还剩18米，原来有多少米？","given":["用去占原来的：2/5","剩下：18米"],"want":"求原来的总量","relation":"原来总量 × 剩余分数 = 剩余量","formula":"18 ÷ (1−2/5)","steps":["单位“1”是原来的总量。","剩下占1−2/5=3/5。","18米对应的是3/5，不是2/5。","原来总量=18÷3/5=30米。"],"answer":"30","answerText":"30","unit":"米","model":{"type":"fraction","mode":"remaining","total":"30","part":"12","rest":"18","k":2,"n":5,"unit":"米"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"先学会这一组的分析方法","id":"f05-0","level":"讲解例题"},{"text":"一批饮料用去了3/8，还剩25升，原来有多少升？","given":["用去占原来的：3/8","剩下：25升"],"want":"求原来的总量","relation":"原来总量 × 剩余分数 = 剩余量","formula":"25 ÷ (1−3/8)","steps":["单位“1”是原来的总量。","剩下占1−3/8=5/8。","25升对应的是5/8，不是3/8。","原来总量=25÷5/8=40升。"],"answer":"40","answerText":"40","unit":"升","model":{"type":"fraction","mode":"remaining","total":"40","part":"15","rest":"25","k":3,"n":8,"unit":"升"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"更换数据，数量关系不变","id":"f05-1","level":"基础变式"},{"text":"一批面粉用去了1/4，还剩27千克，原来有多少千克？","given":["用去占原来的：1/4","剩下：27千克"],"want":"求原来的总量","relation":"原来总量 × 剩余分数 = 剩余量","formula":"27 ÷ (1−1/4)","steps":["单位“1”是原来的总量。","剩下占1−1/4=3/4。","27千克对应的是3/4，不是1/4。","原来总量=27÷3/4=36千克。"],"answer":"36","answerText":"36","unit":"千克","model":{"type":"fraction","mode":"remaining","total":"36","part":"9","rest":"27","k":1,"n":4,"unit":"千克"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"更换情境或问法，仍从同一关系出发","id":"f05-2","level":"情境变式"},{"text":"一批丝带用去了3/7，还剩6米，原来有多少米？","given":["用去占原来的：3/7","剩下：6米"],"want":"求原来的总量","relation":"原来总量 × 剩余分数 = 剩余量","formula":"6 ÷ (1−3/7)","steps":["单位“1”是原来的总量。","剩下占1−3/7=4/7。","6米对应的是4/7，不是3/7。","原来总量=6÷4/7=21/2米。"],"answer":"21/2","answerText":"21/2","unit":"米","model":{"type":"fraction","mode":"remaining","total":"21/2","part":"9/2","rest":"6","k":3,"n":7,"unit":"米"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"增加条件、逆向设问或提高计算要求","id":"f05-3","level":"进阶变式"}],"priority":true,"extension":false},{"id":"f06","c":1,"title":"已知一部分，求另一部分","method":"先求整体，再求另一部分","pages":"7—10的两步变式","trap":"算出总量后，还要回答题目最后的问题。","items":[{"text":"一批卡片中，已经用了24张，占全部的3/5，还没有用的有多少张？","given":["已用：24张","已用占全部的：3/5"],"want":"求还没有用的部分","relation":"先求整体，再用整体减去已知部分","formula":"24 ÷ 3/5 − 24","steps":["先求全部：24÷3/5=40张。","再求未用：40−24=16张。","检查已用与未用之和：24+16=40。"],"answer":"16","answerText":"16","unit":"张","model":{"type":"fraction","mode":"other","total":"40","part":"24","rest":"16","k":3,"n":5,"unit":"张"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"先学会这一组的分析方法","id":"f06-0","level":"讲解例题"},{"text":"一批贴纸中，已经用了24张，占全部的2/3，还没有用的有多少张？","given":["已用：24张","已用占全部的：2/3"],"want":"求还没有用的部分","relation":"先求整体，再用整体减去已知部分","formula":"24 ÷ 2/3 − 24","steps":["先求全部：24÷2/3=36张。","再求未用：36−24=12张。","检查已用与未用之和：24+12=36。"],"answer":"12","answerText":"12","unit":"张","model":{"type":"fraction","mode":"other","total":"36","part":"24","rest":"12","k":2,"n":3,"unit":"张"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"更换数据，数量关系不变","id":"f06-1","level":"基础变式"},{"text":"一批彩纸中，已经用了24张，占全部的3/7，还没有用的有多少张？","given":["已用：24张","已用占全部的：3/7"],"want":"求还没有用的部分","relation":"先求整体，再用整体减去已知部分","formula":"24 ÷ 3/7 − 24","steps":["先求全部：24÷3/7=56张。","再求未用：56−24=32张。","检查已用与未用之和：24+32=56。"],"answer":"32","answerText":"32","unit":"张","model":{"type":"fraction","mode":"other","total":"56","part":"24","rest":"32","k":3,"n":7,"unit":"张"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"更换情境或问法，仍从同一关系出发","id":"f06-2","level":"情境变式"},{"text":"一批绳子中，已经用了3米，占全部的2/5，还没有用的有多少米？","given":["已用：3米","已用占全部的：2/5"],"want":"求还没有用的部分","relation":"先求整体，再用整体减去已知部分","formula":"3 ÷ 2/5 − 3","steps":["先求全部：3÷2/5=15/2米。","再求未用：15/2−3=9/2米。","检查已用与未用之和：3+9/2=15/2。"],"answer":"9/2","answerText":"9/2","unit":"米","model":{"type":"fraction","mode":"other","total":"15/2","part":"3","rest":"9/2","k":2,"n":5,"unit":"米"},"ask":["单位“1”是谁，已知还是未知？","已知的量对应图中的哪几份？","求的是整体还是部分？"],"change":"增加条件、逆向设问或提高计算要求","id":"f06-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"f07","c":1,"title":"两个量之间的倍数关系","method":"先确定“谁是谁的几分之几”","pages":"7—8","trap":"“甲是乙的几分之几”，单位“1”是乙。","items":[{"text":"红色彩带的长度是蓝色的3/4。蓝色长20米，红色长多少米？","given":["红色是蓝色的3/4","蓝色：20米"],"want":"求红色长度","relation":"蓝色长度 × 对应分数 = 红色长度","formula":"20×3/4","steps":["“是蓝色的3/4”，蓝色是作为比较标准的单位“1”。","红色长度=蓝色长度×3/4。","蓝色已知，用20×3/4=15。"],"answer":"15","answerText":"15","unit":"米","model":{"type":"ratio","total":"20","part":"15","k":3,"n":4,"reverse":false,"unit":"米"},"ask":["“是谁的几分之几”，谁是比较标准？","比较标准的量已知吗？"],"change":"先学会这一组的分析方法","id":"f07-0","level":"讲解例题"},{"text":"红色彩带的长度是蓝色的3/4。红色长15米，蓝色长多少米？","given":["红色是蓝色的3/4","红色：15米"],"want":"求蓝色长度","relation":"蓝色长度 × 对应分数 = 红色长度","formula":"15÷3/4","steps":["“是蓝色的3/4”，蓝色是作为比较标准的单位“1”。","红色长度=蓝色长度×3/4。","蓝色未知，用15÷3/4=20。"],"answer":"20","answerText":"20","unit":"米","model":{"type":"ratio","total":"20","part":"15","k":3,"n":4,"reverse":true,"unit":"米"},"ask":["“是谁的几分之几”，谁是比较标准？","比较标准的量已知吗？"],"change":"更换数据，数量关系不变","id":"f07-1","level":"基础变式"},{"text":"红色丝带的长度是蓝色的5/6。红色长20米，蓝色长多少米？","given":["红色是蓝色的5/6","红色：20米"],"want":"求蓝色长度","relation":"蓝色长度 × 对应分数 = 红色长度","formula":"20÷5/6","steps":["“是蓝色的5/6”，蓝色是作为比较标准的单位“1”。","红色长度=蓝色长度×5/6。","蓝色未知，用20÷5/6=24。"],"answer":"24","answerText":"24","unit":"米","model":{"type":"ratio","total":"24","part":"20","k":5,"n":6,"reverse":true,"unit":"米"},"ask":["“是谁的几分之几”，谁是比较标准？","比较标准的量已知吗？"],"change":"更换情境或问法，仍从同一关系出发","id":"f07-2","level":"情境变式"},{"text":"红色绳子的长度是蓝色的4/3。红色长24米，蓝色长多少米？","given":["红色是蓝色的4/3","红色：24米"],"want":"求蓝色长度","relation":"蓝色长度 × 对应分数 = 红色长度","formula":"24÷4/3","steps":["“是蓝色的4/3”，蓝色是作为比较标准的单位“1”。","红色长度=蓝色长度×4/3。","蓝色未知，用24÷4/3=18。"],"answer":"18","answerText":"18","unit":"米","model":{"type":"ratio","total":"18","part":"24","k":4,"n":3,"reverse":true,"unit":"米"},"ask":["“是谁的几分之几”，谁是比较标准？","比较标准的量已知吗？"],"change":"增加条件、逆向设问或提高计算要求","id":"f07-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"f08","c":1,"title":"求每小时的量","method":"路程÷时间=速度","pages":"10及同关系迁移","trap":"3/4小时的路程，不等于1小时的路程。","items":[{"text":"骑车3/4小时行了45千米，照这个速度，1小时行多少千米？","given":["3/4小时对应45千米","速度保持不变"],"want":"每小时行多少千米","relation":"路程 = 速度 × 时间","formula":"45÷3/4","steps":["要求每小时的路程，就是求速度。","速度=路程÷时间。","45÷3/4=60（千米/时）。"],"answer":"60","answerText":"60","unit":"千米/时","model":{"type":"rate","time":"3/4","distance":"45","targetTime":"1","targetDistance":"60","findtime":false},"ask":["这是几小时的量？题目要几小时的量？","需要先求1小时行多少吗？"],"change":"先学会这一组的分析方法","id":"f08-0","level":"讲解例题"},{"text":"骑车2/3小时行了40千米，照这个速度，1小时行多少千米？","given":["2/3小时对应40千米","速度保持不变"],"want":"每小时行多少千米","relation":"路程 = 速度 × 时间","formula":"40÷2/3","steps":["要求每小时的路程，就是求速度。","速度=路程÷时间。","40÷2/3=60（千米/时）。"],"answer":"60","answerText":"60","unit":"千米/时","model":{"type":"rate","time":"2/3","distance":"40","targetTime":"1","targetDistance":"60","findtime":false},"ask":["这是几小时的量？题目要几小时的量？","需要先求1小时行多少吗？"],"change":"更换数据，数量关系不变","id":"f08-1","level":"基础变式"},{"text":"乘车5/6小时行了50千米，照这个速度，1小时行多少千米？","given":["5/6小时对应50千米","速度保持不变"],"want":"每小时行多少千米","relation":"路程 = 速度 × 时间","formula":"50÷5/6","steps":["要求每小时的路程，就是求速度。","速度=路程÷时间。","50÷5/6=60（千米/时）。"],"answer":"60","answerText":"60","unit":"千米/时","model":{"type":"rate","time":"5/6","distance":"50","targetTime":"1","targetDistance":"60","findtime":false},"ask":["这是几小时的量？题目要几小时的量？","需要先求1小时行多少吗？"],"change":"更换情境或问法，仍从同一关系出发","id":"f08-2","level":"情境变式"},{"text":"骑行7/8小时行了21/2千米，照这个速度，1小时行多少千米？","given":["7/8小时对应21/2千米","速度保持不变"],"want":"每小时行多少千米","relation":"路程 = 速度 × 时间","formula":"21/2÷7/8","steps":["要求每小时的路程，就是求速度。","速度=路程÷时间。","21/2÷7/8=12（千米/时）。"],"answer":"12","answerText":"12","unit":"千米/时","model":{"type":"rate","time":"7/8","distance":"21/2","targetTime":"1","targetDistance":"12","findtime":false},"ask":["这是几小时的量？题目要几小时的量？","需要先求1小时行多少吗？"],"change":"增加条件、逆向设问或提高计算要求","id":"f08-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"f09","c":1,"title":"先求单位量，再求路程或时间","method":"先求速度，再求目标量","pages":"10的两步迁移","trap":"先求出的速度只是中间结果。","items":[{"text":"骑车3/4小时行45千米，照此速度，5/6小时能行多少千米？","given":["3/4小时对应45千米","速度保持不变"],"want":"5/6小时的路程","relation":"路程 = 速度 × 时间","formula":"(45÷3/4)×5/6","steps":["先求速度：45÷3/4=60（千米/时）。","再求路程：60×5/6=50（千米）。","两个时间都用小时，单位一致。"],"answer":"50","answerText":"50","unit":"千米","model":{"type":"rate","time":"3/4","distance":"45","targetTime":"5/6","targetDistance":"50","findtime":false},"ask":["这是几小时的量？题目要几小时的量？","需要先求1小时行多少吗？"],"change":"先学会这一组的分析方法","id":"f09-0","level":"讲解例题"},{"text":"骑车2/3小时行40千米，照此速度，行90千米需要多少小时？","given":["2/3小时对应40千米","速度保持不变"],"want":"行90千米需要的时间","relation":"路程 = 速度 × 时间","formula":"90÷(40÷2/3)","steps":["先求每小时路程：40÷2/3=60（千米/时）。","再用路程÷速度：90÷60=3/2（小时）。","注意题目最后问时间，不是速度。"],"answer":"3/2","answerText":"3/2","unit":"小时","model":{"type":"rate","time":"2/3","distance":"40","targetTime":"3/2","targetDistance":"90","findtime":true},"ask":["这是几小时的量？题目要几小时的量？","需要先求1小时行多少吗？"],"change":"更换数据，数量关系不变","id":"f09-1","level":"基础变式"},{"text":"骑车5/8小时行25千米，照此速度，3/4小时能行多少千米？","given":["5/8小时对应25千米","速度保持不变"],"want":"3/4小时的路程","relation":"路程 = 速度 × 时间","formula":"(25÷5/8)×3/4","steps":["先求速度：25÷5/8=40（千米/时）。","再求路程：40×3/4=30（千米）。","两个时间都用小时，单位一致。"],"answer":"30","answerText":"30","unit":"千米","model":{"type":"rate","time":"5/8","distance":"25","targetTime":"3/4","targetDistance":"30","findtime":false},"ask":["这是几小时的量？题目要几小时的量？","需要先求1小时行多少吗？"],"change":"更换情境或问法，仍从同一关系出发","id":"f09-2","level":"情境变式"},{"text":"乘车7/10小时行42千米，照此速度，行75千米需要多少小时？","given":["7/10小时对应42千米","速度保持不变"],"want":"行75千米需要的时间","relation":"路程 = 速度 × 时间","formula":"75÷(42÷7/10)","steps":["先求每小时路程：42÷7/10=60（千米/时）。","再用路程÷速度：75÷60=5/4（小时）。","注意题目最后问时间，不是速度。"],"answer":"5/4","answerText":"5/4","unit":"小时","model":{"type":"rate","time":"7/10","distance":"42","targetTime":"5/4","targetDistance":"75","findtime":true},"ask":["这是几小时的量？题目要几小时的量？","需要先求1小时行多少吗？"],"change":"增加条件、逆向设问或提高计算要求","id":"f09-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"f10","c":1,"title":"已知面积和一条边，求另一条边","method":"面积÷已知边长","pages":"4—5","trap":"面积和边长的单位不同，不能直接相减。","items":[{"text":"一块长方形布面积是3/4平方米，宽1/2米，长是多少米？","given":["面积：3/4平方米","宽：1/2米"],"want":"求长","relation":"长 × 宽 = 面积","formula":"3/4÷1/2","steps":["先写熟悉的关系：长×宽=面积。","长=面积÷宽=3/4÷1/2=3/2（米）。","检验：3/2×1/2=3/4（平方米）。"],"answer":"3/2","answerText":"3/2","unit":"米","model":{"type":"rect","area":"3/4","width":"1/2"},"ask":["面积是长和宽相乘得到的吗？","现在缺少哪个因数？"],"change":"先学会这一组的分析方法","id":"f10-0","level":"讲解例题"},{"text":"一块长方形布面积是4/5平方米，宽2/3米，长是多少米？","given":["面积：4/5平方米","宽：2/3米"],"want":"求长","relation":"长 × 宽 = 面积","formula":"4/5÷2/3","steps":["先写熟悉的关系：长×宽=面积。","长=面积÷宽=4/5÷2/3=6/5（米）。","检验：6/5×2/3=4/5（平方米）。"],"answer":"6/5","answerText":"6/5","unit":"米","model":{"type":"rect","area":"4/5","width":"2/3"},"ask":["面积是长和宽相乘得到的吗？","现在缺少哪个因数？"],"change":"更换数据，数量关系不变","id":"f10-1","level":"基础变式"},{"text":"一块长方形布面积是5/6平方米，宽5/9米，长是多少米？","given":["面积：5/6平方米","宽：5/9米"],"want":"求长","relation":"长 × 宽 = 面积","formula":"5/6÷5/9","steps":["先写熟悉的关系：长×宽=面积。","长=面积÷宽=5/6÷5/9=3/2（米）。","检验：3/2×5/9=5/6（平方米）。"],"answer":"3/2","answerText":"3/2","unit":"米","model":{"type":"rect","area":"5/6","width":"5/9"},"ask":["面积是长和宽相乘得到的吗？","现在缺少哪个因数？"],"change":"更换情境或问法，仍从同一关系出发","id":"f10-2","level":"情境变式"},{"text":"一块长方形布面积是7/8平方米，宽7/12米，长是多少米？","given":["面积：7/8平方米","宽：7/12米"],"want":"求长","relation":"长 × 宽 = 面积","formula":"7/8÷7/12","steps":["先写熟悉的关系：长×宽=面积。","长=面积÷宽=7/8÷7/12=3/2（米）。","检验：3/2×7/12=7/8（平方米）。"],"answer":"3/2","answerText":"3/2","unit":"米","model":{"type":"rect","area":"7/8","width":"7/12"},"ask":["面积是长和宽相乘得到的吗？","现在缺少哪个因数？"],"change":"增加条件、逆向设问或提高计算要求","id":"f10-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"f11","c":1,"title":"进阶：连续平均分","method":"先确定总共分成几份","pages":"分数除法（一）的进阶变式","trap":"先分2壶再分3杯，一共6杯，不是5杯。","items":[{"text":"有3/4升果汁，先平均倒进2个壶，再把每壶平均分成3杯，每杯多少升？","given":["总量：3/4升","2个壶，每壶3杯"],"want":"求每杯果汁量","relation":"先求一壶，再求一杯；也可先求总杯数","formula":"3/4÷2÷3","steps":["每壶：3/4÷2=3/8（升）。","每杯：3/8÷3=1/8（升）。","也可直接算3/4÷(2×3)=1/8。"],"answer":"1/8","answerText":"1/8","unit":"升","model":{"type":"share","a":3,"b":4,"n":6},"ask":["一共有多少杯？","每杯是总量的几分之一？"],"change":"先学会这一组的分析方法","id":"f11-0","level":"讲解例题"},{"text":"有5/6升果汁，先平均倒进2个壶，再把每壶平均分成5杯，每杯多少升？","given":["总量：5/6升","2个壶，每壶5杯"],"want":"求每杯果汁量","relation":"先求一壶，再求一杯；也可先求总杯数","formula":"5/6÷2÷5","steps":["每壶：5/6÷2=5/12（升）。","每杯：5/12÷5=1/12（升）。","也可直接算5/6÷(2×5)=1/12。"],"answer":"1/12","answerText":"1/12","unit":"升","model":{"type":"share","a":5,"b":6,"n":10},"ask":["一共有多少杯？","每杯是总量的几分之一？"],"change":"更换数据，数量关系不变","id":"f11-1","level":"基础变式"},{"text":"有7/8升果汁，先平均倒进3个壶，再把每壶平均分成2杯，每杯多少升？","given":["总量：7/8升","3个壶，每壶2杯"],"want":"求每杯果汁量","relation":"先求一壶，再求一杯；也可先求总杯数","formula":"7/8÷3÷2","steps":["每壶：7/8÷3=7/24（升）。","每杯：7/24÷2=7/48（升）。","也可直接算7/8÷(3×2)=7/48。"],"answer":"7/48","answerText":"7/48","unit":"升","model":{"type":"share","a":7,"b":8,"n":6},"ask":["一共有多少杯？","每杯是总量的几分之一？"],"change":"更换情境或问法，仍从同一关系出发","id":"f11-2","level":"情境变式"},{"text":"有9/10升果汁，先平均倒进3个壶，再把每壶平均分成4杯，每杯多少升？","given":["总量：9/10升","3个壶，每壶4杯"],"want":"求每杯果汁量","relation":"先求一壶，再求一杯；也可先求总杯数","formula":"9/10÷3÷4","steps":["每壶：9/10÷3=3/10（升）。","每杯：3/10÷4=3/40（升）。","也可直接算9/10÷(3×4)=3/40。"],"answer":"3/40","answerText":"3/40","unit":"升","model":{"type":"share","a":9,"b":10,"n":12},"ask":["一共有多少杯？","每杯是总量的几分之一？"],"change":"增加条件、逆向设问或提高计算要求","id":"f11-3","level":"进阶变式"}],"priority":false,"extension":true},{"id":"f12","c":1,"title":"进阶：段数与剪的次数","method":"求段数后回到实际情境","pages":"分数除法（二）的进阶变式","trap":"剪绳题的除法结果通常还不是最后答案。","items":[{"text":"一根绳子长3米，每3/4米剪一段，全部剪完需要剪几次？","given":["总长：3米","每段：3/4米"],"want":"求剪的次数","relation":"先求段数；单根绳子剪的次数 = 段数−1","formula":"(3÷3/4)−1","steps":["段数：3÷3/4=4（段）。","一根绳子剪成4段，只需4−1=3次。","区分“段数”和“剪的次数”。"],"answer":"3","answerText":"3","unit":"次","model":{"type":"groups","total":"3","each":"3/4","cuts":true},"ask":["除法算出来的是段数还是次数？","剪一次会得到几段？"],"change":"先学会这一组的分析方法","id":"f12-0","level":"讲解例题"},{"text":"一根绳子长5/3米，每1/3米剪一段，全部剪完需要剪几次？","given":["总长：5/3米","每段：1/3米"],"want":"求剪的次数","relation":"先求段数；单根绳子剪的次数 = 段数−1","formula":"(5/3÷1/3)−1","steps":["段数：5/3÷1/3=5（段）。","一根绳子剪成5段，只需5−1=4次。","区分“段数”和“剪的次数”。"],"answer":"4","answerText":"4","unit":"次","model":{"type":"groups","total":"5/3","each":"1/3","cuts":true},"ask":["除法算出来的是段数还是次数？","剪一次会得到几段？"],"change":"更换数据，数量关系不变","id":"f12-1","level":"基础变式"},{"text":"一根绳子长7/4米，每1/4米剪一段，全部剪完需要剪几次？","given":["总长：7/4米","每段：1/4米"],"want":"求剪的次数","relation":"先求段数；单根绳子剪的次数 = 段数−1","formula":"(7/4÷1/4)−1","steps":["段数：7/4÷1/4=7（段）。","一根绳子剪成7段，只需7−1=6次。","区分“段数”和“剪的次数”。"],"answer":"6","answerText":"6","unit":"次","model":{"type":"groups","total":"7/4","each":"1/4","cuts":true},"ask":["除法算出来的是段数还是次数？","剪一次会得到几段？"],"change":"更换情境或问法，仍从同一关系出发","id":"f12-2","level":"情境变式"},{"text":"一根绳子长9/5米，每3/10米剪一段，全部剪完需要剪几次？","given":["总长：9/5米","每段：3/10米"],"want":"求剪的次数","relation":"先求段数；单根绳子剪的次数 = 段数−1","formula":"(9/5÷3/10)−1","steps":["段数：9/5÷3/10=6（段）。","一根绳子剪成6段，只需6−1=5次。","区分“段数”和“剪的次数”。"],"answer":"5","answerText":"5","unit":"次","model":{"type":"groups","total":"9/5","each":"3/10","cuts":true},"ask":["除法算出来的是段数还是次数？","剪一次会得到几段？"],"change":"增加条件、逆向设问或提高计算要求","id":"f12-3","level":"进阶变式"}],"priority":false,"extension":true},{"id":"f13","c":1,"title":"进阶：整瓶、剩余与至少需要","method":"商要结合实际问法处理","pages":"分数除法（二）的进阶变式","trap":"装满取整瓶，全部装下还要容纳余量；不能一律四舍五入。","items":[{"text":"有4升饮料，每瓶最多装3/5升。最多装满多少瓶？","given":["总量：4升","每瓶容量：3/5升"],"want":"最多装满多少瓶","relation":"先求总量里有多少个每瓶量，再判断实际问法","formula":"4÷3/5","steps":["先求商：4÷3/5=20/3。","可装满6瓶，已用18/5升，剩下2/5升。","只能计装满的瓶子，所以最多6瓶。"],"answer":"6","answerText":"6","unit":"瓶","model":{"type":"groups","total":"4","each":"3/5","container":true},"ask":["问装满几瓶，还是全部装下至少用几瓶？","最后不足一瓶的部分怎样处理？"],"change":"先学会这一组的分析方法","id":"f13-0","level":"讲解例题"},{"text":"有4升饮料，每瓶最多装3/5升。全部装下至少需要多少瓶？","given":["总量：4升","每瓶容量：3/5升"],"want":"全部装下至少需要多少瓶","relation":"先求总量里有多少个每瓶量，再判断实际问法","formula":"4÷3/5","steps":["先求商：4÷3/5=20/3。","可装满6瓶，已用18/5升，剩下2/5升。","6瓶后还有2/5升，也需要再用1瓶，所以至少7瓶。"],"answer":"7","answerText":"7","unit":"瓶","model":{"type":"groups","total":"4","each":"3/5","container":true},"ask":["问装满几瓶，还是全部装下至少用几瓶？","最后不足一瓶的部分怎样处理？"],"change":"更换数据，数量关系不变","id":"f13-1","level":"基础变式"},{"text":"有4升饮料，每瓶最多装3/5升。装满尽可能多瓶后，余下多少升？","given":["总量：4升","每瓶容量：3/5升"],"want":"装满尽可能多瓶后，余下多少升","relation":"先求总量里有多少个每瓶量，再判断实际问法","formula":"4÷3/5","steps":["先求商：4÷3/5=20/3。","可装满6瓶，已用18/5升，剩下2/5升。","剩余=4−6×3/5=2/5（升）。"],"answer":"2/5","answerText":"2/5","unit":"升","model":{"type":"groups","total":"4","each":"3/5","container":true},"ask":["问装满几瓶，还是全部装下至少用几瓶？","最后不足一瓶的部分怎样处理？"],"change":"更换情境或问法，仍从同一关系出发","id":"f13-2","level":"情境变式"},{"text":"有7/2升饮料，每瓶最多装3/4升。全部装下至少需要多少瓶？","given":["总量：7/2升","每瓶容量：3/4升"],"want":"全部装下至少需要多少瓶","relation":"先求总量里有多少个每瓶量，再判断实际问法","formula":"7/2÷3/4","steps":["先求商：7/2÷3/4=14/3。","可装满4瓶，已用3升，剩下1/2升。","4瓶后还有1/2升，也需要再用1瓶，所以至少5瓶。"],"answer":"5","answerText":"5","unit":"瓶","model":{"type":"groups","total":"7/2","each":"3/4","container":true},"ask":["问装满几瓶，还是全部装下至少用几瓶？","最后不足一瓶的部分怎样处理？"],"change":"增加条件、逆向设问或提高计算要求","id":"f13-3","level":"进阶变式"}],"priority":false,"extension":true},{"id":"c01","c":2,"title":"从实际条件确定半径、直径","method":"先找限制圆大小的长度","pages":"13—14","trap":"最大圆看限制条件；圆规两脚张开的是半径。","items":[{"text":"一块长方形纸板长8厘米、宽8厘米，在里面剪出一个尽可能大的圆，每个圆的半径是多少厘米？","given":["长：8厘米","宽：8厘米","并排1个圆"],"want":"求最大圆的半径","relation":"圆的直径受短边和排列方向同时限制","formula":"min(8, 8÷1)÷2","steps":["圆的直径不能超过宽8厘米。","沿长边放1个圆，每个直径还不能超过8÷1=8厘米。","所以最大直径8厘米。","半径=8÷2=4厘米。"],"answer":"4","answerText":"4","unit":"厘米","model":{"type":"square","l":"8","w":"8","count":1,"cut":false},"ask":["哪条边先限制圆的大小？","题目问半径还是直径？"],"change":"先学会这一组的分析方法","id":"c01-0","level":"讲解例题"},{"text":"一块长方形纸板长12厘米、宽7厘米，在里面剪出一个尽可能大的圆，每个圆的直径是多少厘米？","given":["长：12厘米","宽：7厘米","并排1个圆"],"want":"求最大圆的直径","relation":"圆的直径受短边和排列方向同时限制","formula":"min(7, 12÷1)","steps":["圆的直径不能超过宽7厘米。","沿长边放1个圆，每个直径还不能超过12÷1=12厘米。","所以最大直径7厘米。","题目求直径，所以答案为7厘米。"],"answer":"7","answerText":"7","unit":"厘米","model":{"type":"square","l":"12","w":"7","count":1,"cut":false},"ask":["哪条边先限制圆的大小？","题目问半径还是直径？"],"change":"更换数据，数量关系不变","id":"c01-1","level":"基础变式"},{"text":"一块长方形卡纸长10厘米、宽6厘米，在里面剪出一个尽可能大的圆，每个圆的半径是多少厘米？","given":["长：10厘米","宽：6厘米","并排1个圆"],"want":"求最大圆的半径","relation":"圆的直径受短边和排列方向同时限制","formula":"min(6, 10÷1)÷2","steps":["圆的直径不能超过宽6厘米。","沿长边放1个圆，每个直径还不能超过10÷1=10厘米。","所以最大直径6厘米。","半径=6÷2=3厘米。"],"answer":"3","answerText":"3","unit":"厘米","model":{"type":"square","l":"10","w":"6","count":1,"cut":false},"ask":["哪条边先限制圆的大小？","题目问半径还是直径？"],"change":"更换情境或问法，仍从同一关系出发","id":"c01-2","level":"情境变式"},{"text":"一块长方形纸板长12厘米、宽6厘米，在里面并排剪出2个相同的、尽可能大的圆，每个圆的半径是多少厘米？","given":["长：12厘米","宽：6厘米","并排2个圆"],"want":"求最大圆的半径","relation":"圆的直径受短边和排列方向同时限制","formula":"min(6, 12÷2)÷2","steps":["圆的直径不能超过宽6厘米。","沿长边放2个圆，每个直径还不能超过12÷2=6厘米。","所以最大直径6厘米。","半径=6÷2=3厘米。"],"answer":"3","answerText":"3","unit":"厘米","model":{"type":"square","l":"12","w":"6","count":2,"cut":false},"ask":["哪条边先限制圆的大小？","题目问半径还是直径？"],"change":"增加条件、逆向设问或提高计算要求","id":"c01-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c02","c":2,"title":"整圆周长与围栏","method":"C=πd=2πr","pages":"21—23","trap":"半径要乘2；有入口时，只扣实际不围的长度。","items":[{"text":"圆形花坛的半径是3米，沿边缘围一圈，需要约多少米？","given":["半径：3米"],"want":"求需要围的长度","relation":"先求圆周长，再判断是否全部围起来","formula":"2×3.14×3","steps":["题目求边缘一圈的长度，用周长公式。","C≈2×3.14×3=18.84米。","沿整个圆周围一圈，约需18.84米。"],"answer":"471/25","answerText":"18.84","unit":"米","model":{"type":"circle","r":"3","given":"r","value":"3","measure":"C","gap":"0"},"ask":["求的是边界的长度，还是里面的面积？","给的是半径还是直径？"],"change":"先学会这一组的分析方法","id":"c02-0","level":"讲解例题"},{"text":"圆形水池的直径是8米，沿边缘围一圈，需要约多少米？","given":["直径：8米"],"want":"求需要围的长度","relation":"先求圆周长，再判断是否全部围起来","formula":"3.14×8","steps":["题目求边缘一圈的长度，用周长公式。","C≈2×3.14×4=25.12米。","沿整个圆周围一圈，约需25.12米。"],"answer":"628/25","answerText":"25.12","unit":"米","model":{"type":"circle","r":"4","given":"d","value":"8","measure":"C","gap":"0"},"ask":["求的是边界的长度，还是里面的面积？","给的是半径还是直径？"],"change":"更换数据，数量关系不变","id":"c02-1","level":"基础变式"},{"text":"圆形草坪的半径是5米，沿边缘围一圈，需要约多少米？","given":["半径：5米"],"want":"求需要围的长度","relation":"先求圆周长，再判断是否全部围起来","formula":"2×3.14×5","steps":["题目求边缘一圈的长度，用周长公式。","C≈2×3.14×5=31.4米。","沿整个圆周围一圈，约需31.4米。"],"answer":"157/5","answerText":"31.4","unit":"米","model":{"type":"circle","r":"5","given":"r","value":"5","measure":"C","gap":"0"},"ask":["求的是边界的长度，还是里面的面积？","给的是半径还是直径？"],"change":"更换情境或问法，仍从同一关系出发","id":"c02-2","level":"情境变式"},{"text":"圆形花坛的半径是4米，留出2米的入口，其余部分围栏杆，需要约多少米栏杆？","given":["半径：4米","入口：2米"],"want":"求需要围的长度","relation":"先求圆周长，再判断是否全部围起来","formula":"2×3.14×4−2","steps":["题目求边缘一圈的长度，用周长公式。","C≈2×3.14×4=25.12米。","扣除入口：25.12−2=23.12米。"],"answer":"578/25","answerText":"23.12","unit":"米","model":{"type":"circle","r":"4","given":"r","value":"4","measure":"C","gap":"2"},"ask":["求的是边界的长度，还是里面的面积？","给的是半径还是直径？"],"change":"增加条件、逆向设问或提高计算要求","id":"c02-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c03","c":2,"title":"已知周长，求半径或直径","method":"先求一圈长度，再逆用公式","pages":"31","trap":"绕10圈的绳长要先除以10。","items":[{"text":"一根长31.4米的绳子，正好沿圆形物体外缘绕1圈，忽略绳子粗细和接头。这个圆的直径约多少米？","given":["绳长：31.4米","正好绕1圈"],"want":"求圆的直径","relation":"先求每圈周长，再由周长反求所需量","formula":"31.4÷1÷3.14","steps":["一圈周长=31.4÷1=31.4米。","直径≈31.4÷3.14=10米。","题目求直径，答案约10米。"],"answer":"10","answerText":"10","unit":"米","model":{"type":"circle","r":"5","given":"C","value":"31.4","measure":"inverse"},"ask":["绳子总长是不是一圈周长？","求出直径后，题目还要不要除以2？"],"change":"先学会这一组的分析方法","id":"c03-0","level":"讲解例题"},{"text":"一根长25.12米的绳子，正好沿圆形物体外缘绕1圈，忽略绳子粗细和接头。这个圆的半径约多少米？","given":["绳长：25.12米","正好绕1圈"],"want":"求圆的半径","relation":"先求每圈周长，再由周长反求所需量","formula":"25.12÷1÷3.14÷2","steps":["一圈周长=25.12÷1=25.12米。","直径≈25.12÷3.14=8米。","半径=8÷2=4米。"],"answer":"4","answerText":"4","unit":"米","model":{"type":"circle","r":"4","given":"C","value":"25.12","measure":"inverse"},"ask":["绳子总长是不是一圈周长？","求出直径后，题目还要不要除以2？"],"change":"更换数据，数量关系不变","id":"c03-1","level":"基础变式"},{"text":"一根长12.56米的绳子，正好沿圆形物体外缘绕10圈，忽略绳子粗细和接头。这个圆的直径约多少米？","given":["绳长：12.56米","正好绕10圈"],"want":"求圆的直径","relation":"先求每圈周长，再由周长反求所需量","formula":"12.56÷10÷3.14","steps":["一圈周长=12.56÷10=1.256米。","直径≈1.256÷3.14=0.4米。","题目求直径，答案约0.4米。"],"answer":"2/5","answerText":"0.4","unit":"米","model":{"type":"circle","r":"1/5","given":"C","value":"1.256","measure":"inverse"},"ask":["绳子总长是不是一圈周长？","求出直径后，题目还要不要除以2？"],"change":"更换情境或问法，仍从同一关系出发","id":"c03-2","level":"情境变式"},{"text":"一根长37.68米的绳子，正好沿圆形物体外缘绕3圈，忽略绳子粗细和接头。这个圆的半径约多少米？","given":["绳长：37.68米","正好绕3圈"],"want":"求圆的半径","relation":"先求每圈周长，再由周长反求所需量","formula":"37.68÷3÷3.14÷2","steps":["一圈周长=37.68÷3=12.56米。","直径≈12.56÷3.14=4米。","半径=4÷2=2米。"],"answer":"2","answerText":"2","unit":"米","model":{"type":"circle","r":"2","given":"C","value":"12.56","measure":"inverse"},"ask":["绳子总长是不是一圈周长？","求出直径后，题目还要不要除以2？"],"change":"增加条件、逆向设问或提高计算要求","id":"c03-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c04","c":2,"title":"半圆弧长：只求弯曲部分","method":"整圆周长÷2","pages":"22—23、31","trap":"半圈为什么除以2：整圈被平均分成2份，取其中1份。","items":[{"text":"一个半圆形花坛，半径是3米，求它弯曲边缘的长度（不包括直径），约是多少米？","given":["半径：3米","求：弯曲边缘的长度（不包括直径）"],"want":"求弯曲边缘的长度（不包括直径）","relation":"半圆弧长 = 整圆周长 ÷ 2","formula":"3.14×3","steps":["先确定半径：r=3米。","曲线只占整圆周长的一半：2×3.14×3÷2=9.42米。","直径不在所求范围内，不加直径。"],"answer":"471/50","answerText":"9.42","unit":"米","model":{"type":"half","r":"3","given":"r","value":"3","measure":"arc","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"先学会这一组的分析方法","id":"c04-0","level":"讲解例题"},{"text":"一个靠墙的半圆形鸡舍，直径是8米，求它弯曲边缘的长度（不包括直径），约是多少米？","given":["直径：8米","求：弯曲边缘的长度（不包括直径）"],"want":"求弯曲边缘的长度（不包括直径）","relation":"半圆弧长 = 整圆周长 ÷ 2","formula":"3.14×4","steps":["先确定半径：r=4米。","曲线只占整圆周长的一半：2×3.14×4÷2=12.56米。","直径不在所求范围内，不加直径。"],"answer":"314/25","answerText":"12.56","unit":"米","model":{"type":"half","r":"4","given":"d","value":"8","measure":"arc","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"更换数据，数量关系不变","id":"c04-1","level":"基础变式"},{"text":"一个半圆形拱门，半径是5米，求它弯曲边缘的长度（不包括直径），约是多少米？","given":["半径：5米","求：弯曲边缘的长度（不包括直径）"],"want":"求弯曲边缘的长度（不包括直径）","relation":"半圆弧长 = 整圆周长 ÷ 2","formula":"3.14×5","steps":["先确定半径：r=5米。","曲线只占整圆周长的一半：2×3.14×5÷2=15.7米。","直径不在所求范围内，不加直径。"],"answer":"157/10","answerText":"15.7","unit":"米","model":{"type":"half","r":"5","given":"r","value":"5","measure":"arc","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"更换情境或问法，仍从同一关系出发","id":"c04-2","level":"情境变式"},{"text":"有2个相同的半圆形花坛，直径是6米，求它们合计弯曲边缘的长度（不包括直径），约是多少米？","given":["直径：6米","求：弯曲边缘的长度（不包括直径）"],"want":"求弯曲边缘的长度（不包括直径）","relation":"半圆弧长 = 整圆周长 ÷ 2","formula":"(3.14×3)×2","steps":["先确定半径：r=3米。","曲线只占整圆周长的一半：2×3.14×3÷2=9.42米。","直径不在所求范围内，不加直径。","2个合计再乘2，约18.84米。"],"answer":"471/25","answerText":"18.84","unit":"米","model":{"type":"half","r":"3","given":"d","value":"6","measure":"arc","count":2},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"增加条件、逆向设问或提高计算要求","id":"c04-3","level":"进阶变式"}],"priority":true,"extension":false},{"id":"c05","c":2,"title":"半圆周长：曲线加直径","method":"半个圆周＋直径","pages":"22—23","trap":"半圆的周长不等于整圆周长的一半。","items":[{"text":"一个半圆形花坛，半径是3米，求它整个边界的长度（包括直径），约是多少米？","given":["半径：3米","求：整个边界的长度（包括直径）"],"want":"求整个边界的长度（包括直径）","relation":"半圆周长 = 半圆弧长 + 直径","formula":"3.14×3+2×3","steps":["先确定半径：r=3米。","弯曲部分≈3.14×3=9.42米。","再加直径6米：9.42+6=15.42米。"],"answer":"771/50","answerText":"15.42","unit":"米","model":{"type":"half","r":"3","given":"r","value":"3","measure":"perimeter","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"先学会这一组的分析方法","id":"c05-0","level":"讲解例题"},{"text":"一个半圆形纸片，直径是8米，求它整个边界的长度（包括直径），约是多少米？","given":["直径：8米","求：整个边界的长度（包括直径）"],"want":"求整个边界的长度（包括直径）","relation":"半圆周长 = 半圆弧长 + 直径","formula":"3.14×4+2×4","steps":["先确定半径：r=4米。","弯曲部分≈3.14×4=12.56米。","再加直径8米：12.56+8=20.56米。"],"answer":"514/25","answerText":"20.56","unit":"米","model":{"type":"half","r":"4","given":"d","value":"8","measure":"perimeter","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"更换数据，数量关系不变","id":"c05-1","level":"基础变式"},{"text":"一个半圆形草坪，半径是5米，求它整个边界的长度（包括直径），约是多少米？","given":["半径：5米","求：整个边界的长度（包括直径）"],"want":"求整个边界的长度（包括直径）","relation":"半圆周长 = 半圆弧长 + 直径","formula":"3.14×5+2×5","steps":["先确定半径：r=5米。","弯曲部分≈3.14×5=15.7米。","再加直径10米：15.7+10=25.7米。"],"answer":"257/10","answerText":"25.7","unit":"米","model":{"type":"half","r":"5","given":"r","value":"5","measure":"perimeter","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"更换情境或问法，仍从同一关系出发","id":"c05-2","level":"情境变式"},{"text":"有2个相同的半圆形花坛，直径是6米，求它们合计整个边界的长度（包括直径），约是多少米？","given":["直径：6米","求：整个边界的长度（包括直径）"],"want":"求整个边界的长度（包括直径）","relation":"半圆周长 = 半圆弧长 + 直径","formula":"(3.14×3+2×3)×2","steps":["先确定半径：r=3米。","弯曲部分≈3.14×3=9.42米。","再加直径6米：9.42+6=15.42米。","2个合计再乘2，约30.84米。"],"answer":"771/25","answerText":"30.84","unit":"米","model":{"type":"half","r":"3","given":"d","value":"6","measure":"perimeter","count":2},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"增加条件、逆向设问或提高计算要求","id":"c05-3","level":"进阶变式"}],"priority":true,"extension":false},{"id":"c06","c":2,"title":"组合图形的外边界","method":"只计算沿外边能走到的线段和弧","pages":"22—23、29","trap":"内部辅助线、拼接线不算周长。","items":[{"text":"一个运动场由中间的长方形和两端的半圆组成，中间长方形长50米、宽20米。沿外边缘走一圈约多少米？","given":["直道长：50米","宽：20米"],"want":"求外边界长度","relation":"两段弧合成整圆；再与直道长度或长方形面积组合","formula":"2×50+2×3.14×10","steps":["半圆直径等于宽20米，半径为10米。","两端半圆弧合成一整圈，约2×3.14×10=62.8米。","再加两条直道：50×2+62.8=162.8米。","内部的两条直径不计入外边界。"],"answer":"814/5","answerText":"162.8","unit":"米","model":{"type":"track","l":"50","w":"20","measure":"C","overall":false,"total":"50"},"ask":["两端的两个半圆能合成什么？","内部直径是否属于外边界？"],"change":"先学会这一组的分析方法","id":"c06-0","level":"讲解例题"},{"text":"一个运动场由中间的长方形和两端的半圆组成，中间长方形长30米、宽10米。沿外边缘走一圈约多少米？","given":["直道长：30米","宽：10米"],"want":"求外边界长度","relation":"两段弧合成整圆；再与直道长度或长方形面积组合","formula":"2×30+2×3.14×5","steps":["半圆直径等于宽10米，半径为5米。","两端半圆弧合成一整圈，约2×3.14×5=31.4米。","再加两条直道：30×2+31.4=91.4米。","内部的两条直径不计入外边界。"],"answer":"457/5","answerText":"91.4","unit":"米","model":{"type":"track","l":"30","w":"10","measure":"C","overall":false,"total":"30"},"ask":["两端的两个半圆能合成什么？","内部直径是否属于外边界？"],"change":"更换数据，数量关系不变","id":"c06-1","level":"基础变式"},{"text":"一个运动场由中间的长方形和两端的半圆组成，整个运动场最左到最右共66米，宽20米。沿外边缘走一圈约多少米？","given":["总长：66米","宽：20米"],"want":"求外边界长度","relation":"两段弧合成整圆；再与直道长度或长方形面积组合","formula":"2×46+2×3.14×10","steps":["半圆直径等于宽20米，半径为10米。","中间直道长=总长−一个直径=66−20=46米。","两端半圆弧合成一整圈，约2×3.14×10=62.8米。","再加两条直道：46×2+62.8=154.8米。","内部的两条直径不计入外边界。"],"answer":"774/5","answerText":"154.8","unit":"米","model":{"type":"track","l":"46","w":"20","measure":"C","overall":true,"total":"66"},"ask":["两端的两个半圆能合成什么？","内部直径是否属于外边界？"],"change":"更换情境或问法，仍从同一关系出发","id":"c06-2","level":"情境变式"},{"text":"一幅图形的外边界由三段弧组成：一段半径4厘米的大半圆弧，两段直径各4厘米的小半圆弧。外边界约多长？","given":["大半圆半径：4厘米","小半圆直径各：4厘米"],"want":"求三段弧的总长度","relation":"先分别求弧长，再相加","formula":"3.14×4+3.14×4","steps":["大弧长≈πr=3.14×4=12.56厘米。","两个小半圆弧合为直径4厘米的一个圆周，约12.56厘米。","总长≈12.56+12.56=25.12厘米；辅助直线不计入。"],"answer":"628/25","answerText":"628/25","unit":"厘米","model":{"type":"curve","r":"4"},"ask":["有几段弧？每段的半径或直径是多少？","辅助线是不是图形的边界？"],"change":"增加条件、逆向设问或提高计算要求","id":"c06-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c07","c":2,"title":"车轮滚动与圈数","method":"一周路程=圆周长","pages":"21—23","trap":"先统一单位，半径不能直接当作直径。","items":[{"text":"圆形车轮的直径是0.5米，在平地无滑动滚动，滚动10周，前进约多少米？","given":["直径：0.5米","无滑动滚动"],"want":"求前进的路程","relation":"路程 = 每周长度 × 周数","formula":"1.57×10","steps":["先把直径换成米：d=0.5米。","一周前进距离≈3.14×0.5=1.57米。","10周前进：1.57×10=15.7米。"],"answer":"157/10","answerText":"15.7","unit":"米","model":{"type":"roll","d":"1/2","cm":false,"turns":"10","distance":"15.7"},"ask":["滚动1周前进的距离是哪一个量？","米和厘米需要先统一吗？"],"change":"先学会这一组的分析方法","id":"c07-0","level":"讲解例题"},{"text":"圆形车轮的直径是0.6米，在平地无滑动滚动，前进了18.84米，大约滚动多少周？","given":["直径：0.6米","无滑动滚动"],"want":"求滚动的圈数","relation":"路程 = 每周长度 × 周数","formula":"18.84÷1.884","steps":["先统一长度单位，直径d=0.6米。","一周距离≈1.884米。","圈数≈18.84÷1.884=10周。"],"answer":"10","answerText":"10","unit":"周","model":{"type":"roll","d":"3/5","cm":false,"turns":"10","distance":"18.84"},"ask":["滚动1周前进的距离是哪一个量？","米和厘米需要先统一吗？"],"change":"更换数据，数量关系不变","id":"c07-1","level":"基础变式"},{"text":"圆形车轮的半径是0.4米，在平地无滑动滚动，滚动15周，前进约多少米？","given":["半径：0.4米","无滑动滚动"],"want":"求前进的路程","relation":"路程 = 每周长度 × 周数","formula":"2.512×15","steps":["先把直径换成米：d=0.8米。","一周前进距离≈3.14×0.8=2.512米。","15周前进：2.512×15=37.68米。"],"answer":"942/25","answerText":"37.68","unit":"米","model":{"type":"roll","d":"4/5","cm":false,"turns":"15","distance":"37.68"},"ask":["滚动1周前进的距离是哪一个量？","米和厘米需要先统一吗？"],"change":"更换情境或问法，仍从同一关系出发","id":"c07-2","level":"情境变式"},{"text":"圆形车轮的半径是20厘米，在平地无滑动滚动，前进了62.8米，大约滚动多少周？","given":["半径：20厘米","无滑动滚动"],"want":"求滚动的圈数","relation":"路程 = 每周长度 × 周数","formula":"62.8÷1.256","steps":["先统一长度单位，直径d=0.4米。","一周距离≈1.256米。","圈数≈62.8÷1.256=50周。"],"answer":"50","answerText":"50","unit":"周","model":{"type":"roll","d":"40","cm":true,"turns":"50","distance":"62.8"},"ask":["滚动1周前进的距离是哪一个量？","米和厘米需要先统一吗？"],"change":"增加条件、逆向设问或提高计算要求","id":"c07-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c08","c":2,"title":"整圆面积与活动范围","method":"S=πr²","pages":"28、31","trap":"喷水距离、拴绳长度通常对应半径；求面积要平方。","items":[{"text":"喷水覆盖范围的半径是3米，面积约多少平方米？","given":["半径：3米"],"want":"求整个圆的面积","relation":"先确定半径，再算 S=πr²","formula":"3.14×3²","steps":["用于面积公式的半径是3米。","半径平方：3×3=9。","S≈3.14×9=28.26平方米。"],"answer":"1413/50","answerText":"28.26","unit":"平方米","model":{"type":"circle","r":"3","given":"r","value":"3","measure":"S","add":"0"},"ask":["覆盖的是一圈边界还是整个区域？","r²是r乘r，还是r乘2？"],"change":"先学会这一组的分析方法","id":"c08-0","level":"讲解例题"},{"text":"圆形草坪的直径是8米，面积约多少平方米？","given":["直径：8米"],"want":"求整个圆的面积","relation":"先确定半径，再算 S=πr²","formula":"3.14×4²","steps":["用于面积公式的半径是4米。","半径平方：4×4=16。","S≈3.14×16=50.24平方米。"],"answer":"1256/25","answerText":"50.24","unit":"平方米","model":{"type":"circle","r":"4","given":"d","value":"8","measure":"S","add":"0"},"ask":["覆盖的是一圈边界还是整个区域？","r²是r乘r，还是r乘2？"],"change":"更换数据，数量关系不变","id":"c08-1","level":"基础变式"},{"text":"羊吃草的无遮挡范围的半径是4米，面积约多少平方米？","given":["半径：4米"],"want":"求整个圆的面积","relation":"先确定半径，再算 S=πr²","formula":"3.14×4²","steps":["用于面积公式的半径是4米。","半径平方：4×4=16。","S≈3.14×16=50.24平方米。"],"answer":"1256/25","answerText":"50.24","unit":"平方米","model":{"type":"circle","r":"4","given":"r","value":"4","measure":"S","add":"0"},"ask":["覆盖的是一圈边界还是整个区域？","r²是r乘r，还是r乘2？"],"change":"更换情境或问法，仍从同一关系出发","id":"c08-2","level":"情境变式"},{"text":"圆形草坪的半径是3米，把它的半径增加1米，扩大后面积约多少平方米？","given":["半径：3米","半径增加：1米"],"want":"求整个圆的面积","relation":"先确定半径，再算 S=πr²","formula":"3.14×4²","steps":["用于面积公式的半径是4米。","半径平方：4×4=16。","S≈3.14×16=50.24平方米。"],"answer":"1256/25","answerText":"50.24","unit":"平方米","model":{"type":"circle","r":"4","given":"r","value":"3","measure":"S","add":"1"},"ask":["覆盖的是一圈边界还是整个区域？","r²是r乘r，还是r乘2？"],"change":"增加条件、逆向设问或提高计算要求","id":"c08-3","level":"进阶变式"}],"priority":true,"extension":false},{"id":"c09","c":2,"title":"已知周长，求面积","method":"先反求半径，再平方","pages":"28—29","trap":"求出直径后还要除以2；不能把周长平方。","items":[{"text":"圆形花坛的周长约18.84米。花坛面积约多少平方米？","given":["一圈周长：18.84米"],"want":"求花坛面积","relation":"周长 → 半径 → 面积","formula":"3.14×(18.84÷1÷3.14÷2)²","steps":["一圈周长=18.84÷1=18.84米。","半径≈18.84÷3.14÷2=3米。","面积≈3.14×3²=28.26平方米。"],"answer":"1413/50","answerText":"28.26","unit":"平方米","model":{"type":"circle","r":"3","given":"C","value":"18.84","measure":"S"},"ask":["周长能直接放进面积公式吗？","需要先求出哪个长度？"],"change":"先学会这一组的分析方法","id":"c09-0","level":"讲解例题"},{"text":"圆形花坛的周长约31.4米。花坛面积约多少平方米？","given":["一圈周长：31.4米"],"want":"求花坛面积","relation":"周长 → 半径 → 面积","formula":"3.14×(31.4÷1÷3.14÷2)²","steps":["一圈周长=31.4÷1=31.4米。","半径≈31.4÷3.14÷2=5米。","面积≈3.14×5²=78.5平方米。"],"answer":"157/2","answerText":"78.5","unit":"平方米","model":{"type":"circle","r":"5","given":"C","value":"31.4","measure":"S"},"ask":["周长能直接放进面积公式吗？","需要先求出哪个长度？"],"change":"更换数据，数量关系不变","id":"c09-1","level":"基础变式"},{"text":"圆形花坛的周长约62.8米。花坛面积约多少平方米？","given":["一圈周长：62.8米"],"want":"求花坛面积","relation":"周长 → 半径 → 面积","formula":"3.14×(62.8÷1÷3.14÷2)²","steps":["一圈周长=62.8÷1=62.8米。","半径≈62.8÷3.14÷2=10米。","面积≈3.14×10²=314平方米。"],"answer":"314","answerText":"314","unit":"平方米","model":{"type":"circle","r":"10","given":"C","value":"62.8","measure":"S"},"ask":["周长能直接放进面积公式吗？","需要先求出哪个长度？"],"change":"更换情境或问法，仍从同一关系出发","id":"c09-2","level":"情境变式"},{"text":"绳子沿圆形花坛边缘正好绕2圈，共长12.56米。花坛面积约多少平方米？","given":["总绳长：12.56米","绕2圈"],"want":"求花坛面积","relation":"周长 → 半径 → 面积","formula":"3.14×(12.56÷2÷3.14÷2)²","steps":["一圈周长=12.56÷2=6.28米。","半径≈6.28÷3.14÷2=1米。","面积≈3.14×1²=3.14平方米。"],"answer":"157/50","answerText":"3.14","unit":"平方米","model":{"type":"circle","r":"1","given":"C","value":"6.28","measure":"S"},"ask":["周长能直接放进面积公式吗？","需要先求出哪个长度？"],"change":"增加条件、逆向设问或提高计算要求","id":"c09-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c10","c":2,"title":"半圆面积","method":"整圆面积÷2","pages":"28—29的对应变式","trap":"求面积不加直径，和半圆周长区分。","items":[{"text":"一个半圆形花坛，半径是3米，求它所占的面积，约是多少平方米？","given":["半径：3米","求：所占的面积"],"want":"求所占的面积","relation":"半圆面积 = 整圆面积 ÷ 2","formula":"3.14×3²÷2","steps":["先确定半径：r=3米。","整圆面积≈3.14×3²=28.26平方米。","取一半：28.26÷2=14.13平方米。","面积不需要加直径。"],"answer":"1413/100","answerText":"14.13","unit":"平方米","model":{"type":"half","r":"3","given":"r","value":"3","measure":"area","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"先学会这一组的分析方法","id":"c10-0","level":"讲解例题"},{"text":"一个半圆形草坪，直径是8米，求它所占的面积，约是多少平方米？","given":["直径：8米","求：所占的面积"],"want":"求所占的面积","relation":"半圆面积 = 整圆面积 ÷ 2","formula":"3.14×4²÷2","steps":["先确定半径：r=4米。","整圆面积≈3.14×4²=50.24平方米。","取一半：50.24÷2=25.12平方米。","面积不需要加直径。"],"answer":"628/25","answerText":"25.12","unit":"平方米","model":{"type":"half","r":"4","given":"d","value":"8","measure":"area","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"更换数据，数量关系不变","id":"c10-1","level":"基础变式"},{"text":"一个半圆形花坛，半径是5米，求它所占的面积，约是多少平方米？","given":["半径：5米","求：所占的面积"],"want":"求所占的面积","relation":"半圆面积 = 整圆面积 ÷ 2","formula":"3.14×5²÷2","steps":["先确定半径：r=5米。","整圆面积≈3.14×5²=78.5平方米。","取一半：78.5÷2=39.25平方米。","面积不需要加直径。"],"answer":"157/4","answerText":"39.25","unit":"平方米","model":{"type":"half","r":"5","given":"r","value":"5","measure":"area","count":1},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"更换情境或问法，仍从同一关系出发","id":"c10-2","level":"情境变式"},{"text":"有2个相同的半圆形花坛，直径是6米，求它们合计所占的面积，约是多少平方米？","given":["直径：6米","求：所占的面积"],"want":"求所占的面积","relation":"半圆面积 = 整圆面积 ÷ 2","formula":"(3.14×3²÷2)×2","steps":["先确定半径：r=3米。","整圆面积≈3.14×3²=28.26平方米。","取一半：28.26÷2=14.13平方米。","面积不需要加直径。","2个合计再乘2，约28.26平方米。"],"answer":"1413/50","answerText":"28.26","unit":"平方米","model":{"type":"half","r":"3","given":"d","value":"6","measure":"area","count":2},"ask":["沿题目要求描一遍，直径要不要算？","求的是长度还是面积？"],"change":"增加条件、逆向设问或提高计算要求","id":"c10-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c11","c":2,"title":"圆环、阴影与剩余面积","method":"大面积减小面积","pages":"29及同关系迁移","trap":"圆环不能用路宽直接平方；小圆偏心不影响面积相减。","items":[{"text":"大圆半径5米、小圆半径3米，两圆圆心相同。去掉小圆后，剩余面积约多少平方米？","given":["内半径：3米","外半径：5米"],"want":"求大圆内、小圆外的面积","relation":"大圆面积 − 小圆面积","formula":"3.14×(5²−3²)","steps":["先分清外半径5米与内半径3米。","外圆面积≈3.14×5²=78.5平方米。","内圆面积≈3.14×3²=28.26平方米。","相减≈78.5−28.26=50.24平方米。"],"answer":"1256/25","answerText":"50.24","unit":"平方米","model":{"type":"ring","R":"5","r":"3","width":false,"off":false},"ask":["路宽是半径，还是两条半径的差？","要留下哪一块区域？"],"change":"先学会这一组的分析方法","id":"c11-0","level":"讲解例题"},{"text":"圆形花坛半径4米，外面修1米宽的小路，小路面积约多少平方米？","given":["内半径：4米","路宽：1米"],"want":"求大圆内、小圆外的面积","relation":"大圆面积 − 小圆面积","formula":"3.14×(5²−4²)","steps":["外半径=4+1=5米。","外圆面积≈3.14×5²=78.5平方米。","内圆面积≈3.14×4²=50.24平方米。","相减≈78.5−50.24=28.26平方米。"],"answer":"1413/50","answerText":"28.26","unit":"平方米","model":{"type":"ring","R":"5","r":"4","width":true,"off":false},"ask":["路宽是半径，还是两条半径的差？","要留下哪一块区域？"],"change":"更换数据，数量关系不变","id":"c11-1","level":"基础变式"},{"text":"边长10厘米的正方形内剪出一个最大的圆，剩下部分的面积约多少平方厘米？","given":["正方形边长：10厘米","剪出一个最大圆"],"want":"求圆外、正方形内的剩余面积","relation":"正方形面积 − 圆面积","formula":"10²−3.14×(10÷2)²","steps":["最大圆直径等于边长，半径=10÷2=5厘米。","正方形面积=10²=100平方厘米。","圆面积≈3.14×5²=78.5平方厘米。","剩余≈100−78.5=21.5平方厘米。"],"answer":"43/2","answerText":"21.5","unit":"平方厘米","model":{"type":"square","l":"10","w":"10","count":1,"cut":true},"ask":["最大圆的直径是什么？","用哪个大面积减哪个小面积？"],"change":"更换情境或问法，仍从同一关系出发","id":"c11-2","level":"情境变式"},{"text":"大圆半径4米、小圆半径2米，小圆偏在一侧但完全在大圆内。去掉小圆后，剩余面积约多少平方米？","given":["内半径：2米","外半径：4米"],"want":"求大圆内、小圆外的面积","relation":"大圆面积 − 小圆面积","formula":"3.14×(4²−2²)","steps":["先分清外半径4米与内半径2米。","外圆面积≈3.14×4²=50.24平方米。","内圆面积≈3.14×2²=12.56平方米。","相减≈50.24−12.56=37.68平方米。"],"answer":"942/25","answerText":"37.68","unit":"平方米","model":{"type":"ring","R":"4","r":"2","width":false,"off":true},"ask":["路宽是半径，还是两条半径的差？","要留下哪一块区域？"],"change":"增加条件、逆向设问或提高计算要求","id":"c11-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c12","c":2,"title":"跑道等组合图形面积","method":"长方形面积＋两个半圆面积","pages":"29","trap":"总长与中间直道长不是同一个量。","items":[{"text":"一个运动场由中间的长方形和两端的半圆组成，中间长方形长50米、宽20米。整个运动场占地面积约多少平方米？","given":["直道长：50米","宽：20米"],"want":"求占地面积","relation":"两段弧合成整圆；再与直道长度或长方形面积组合","formula":"50×20+3.14×10²","steps":["半圆直径等于宽20米，半径为10米。","长方形面积=50×20=1000平方米。","两个半圆面积合为整圆，约3.14×10²=314平方米。","总面积≈1000+314=1314平方米。"],"answer":"1314","answerText":"1314","unit":"平方米","model":{"type":"track","l":"50","w":"20","measure":"S","overall":false,"total":"50"},"ask":["两端的两个半圆能合成什么？","中间长方形的长和宽分别是多少？"],"change":"先学会这一组的分析方法","id":"c12-0","level":"讲解例题"},{"text":"一个运动场由中间的长方形和两端的半圆组成，中间长方形长30米、宽10米。整个运动场占地面积约多少平方米？","given":["直道长：30米","宽：10米"],"want":"求占地面积","relation":"两段弧合成整圆；再与直道长度或长方形面积组合","formula":"30×10+3.14×5²","steps":["半圆直径等于宽10米，半径为5米。","长方形面积=30×10=300平方米。","两个半圆面积合为整圆，约3.14×5²=78.5平方米。","总面积≈300+78.5=378.5平方米。"],"answer":"757/2","answerText":"378.5","unit":"平方米","model":{"type":"track","l":"30","w":"10","measure":"S","overall":false,"total":"30"},"ask":["两端的两个半圆能合成什么？","中间长方形的长和宽分别是多少？"],"change":"更换数据，数量关系不变","id":"c12-1","level":"基础变式"},{"text":"一个运动场由中间的长方形和两端的半圆组成，中间长方形长40米、宽16米。整个运动场占地面积约多少平方米？","given":["直道长：40米","宽：16米"],"want":"求占地面积","relation":"两段弧合成整圆；再与直道长度或长方形面积组合","formula":"40×16+3.14×8²","steps":["半圆直径等于宽16米，半径为8米。","长方形面积=40×16=640平方米。","两个半圆面积合为整圆，约3.14×8²=200.96平方米。","总面积≈640+200.96=840.96平方米。"],"answer":"21024/25","answerText":"840.96","unit":"平方米","model":{"type":"track","l":"40","w":"16","measure":"S","overall":false,"total":"40"},"ask":["两端的两个半圆能合成什么？","中间长方形的长和宽分别是多少？"],"change":"更换情境或问法，仍从同一关系出发","id":"c12-2","level":"情境变式"},{"text":"一个运动场由中间的长方形和两端的半圆组成，整个运动场最左到最右共66米，宽20米。整个运动场占地面积约多少平方米？","given":["总长：66米","宽：20米"],"want":"求占地面积","relation":"两段弧合成整圆；再与直道长度或长方形面积组合","formula":"46×20+3.14×10²","steps":["半圆直径等于宽20米，半径为10米。","中间直道长=总长−一个直径=66−20=46米。","长方形面积=46×20=920平方米。","两个半圆面积合为整圆，约3.14×10²=314平方米。","总面积≈920+314=1234平方米。"],"answer":"1234","answerText":"1234","unit":"平方米","model":{"type":"track","l":"46","w":"20","measure":"S","overall":true,"total":"66"},"ask":["两端的两个半圆能合成什么？","中间长方形的长和宽分别是多少？"],"change":"增加条件、逆向设问或提高计算要求","id":"c12-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c13","c":2,"title":"面积与费用","method":"先求面积，再与单价、总价对应","pages":"28—31的生活变式","trap":"每平方米收费，要用面积，不用周长。","items":[{"text":"一块圆形草坪的半径是3米，每平方米铺草10元，铺满共需约多少元？","given":["半径：3米","每平方米：10元"],"want":"求铺满的总费用","relation":"总费用 = 面积 × 每平方米费用","formula":"28.26×10","steps":["先求半径r=3米。","铺草面积≈3.14×3²=28.26平方米。","总费用≈28.26×10=282.6元。"],"answer":"1413/5","answerText":"282.6","unit":"元","model":{"type":"circle","r":"3","given":"r","value":"3","measure":"S","price":"10"},"ask":["收费按每米还是每平方米？","面积是中间量还是最后答案？"],"change":"先学会这一组的分析方法","id":"c13-0","level":"讲解例题"},{"text":"一块圆形草坪的直径是8米，每平方米铺草12元，铺满共需约多少元？","given":["直径：8米","每平方米：12元"],"want":"求铺满的总费用","relation":"总费用 = 面积 × 每平方米费用","formula":"50.24×12","steps":["先求半径r=4米。","铺草面积≈3.14×4²=50.24平方米。","总费用≈50.24×12=602.88元。"],"answer":"15072/25","answerText":"602.88","unit":"元","model":{"type":"circle","r":"4","given":"d","value":"8","measure":"S","price":"12"},"ask":["收费按每米还是每平方米？","面积是中间量还是最后答案？"],"change":"更换数据，数量关系不变","id":"c13-1","level":"基础变式"},{"text":"一块半圆形草坪的半径是4米，每平方米铺草15元，铺满共需约多少元？","given":["半径：4米","每平方米：15元"],"want":"求铺满的总费用","relation":"总费用 = 面积 × 每平方米费用","formula":"25.12×15","steps":["先求半径r=4米。","铺草面积≈3.14×4²÷2=25.12平方米。","总费用≈25.12×15=376.8元。"],"answer":"1884/5","answerText":"376.8","unit":"元","model":{"type":"half","r":"4","given":"r","value":"4","measure":"area","price":"15"},"ask":["收费按每米还是每平方米？","面积是中间量还是最后答案？"],"change":"更换情境或问法，仍从同一关系出发","id":"c13-2","level":"情境变式"},{"text":"一块圆形草坪的直径是8米，铺满共花602.88元，每平方米费用约多少元？","given":["直径：8米","总费用：602.88元"],"want":"求每平方米费用","relation":"总费用 = 面积 × 每平方米费用","formula":"602.88÷50.24","steps":["先求半径r=4米。","铺草面积≈3.14×4²=50.24平方米。","每平方米费用≈602.88÷50.24=12元。"],"answer":"12","answerText":"12","unit":"元/平方米","model":{"type":"circle","r":"4","given":"d","value":"8","measure":"S","price":"12"},"ask":["收费按每米还是每平方米？","面积是中间量还是最后答案？"],"change":"增加条件、逆向设问或提高计算要求","id":"c13-3","level":"进阶变式"}],"priority":false,"extension":false},{"id":"c14","c":2,"title":"图形变化与方案比较","method":"分别计算，不凭外观判断","pages":"28、31—32","trap":"比较总面积；同周长不一定同面积。","items":[{"text":"方案甲建1个直径8米的大圆花坛，方案乙建2个直径4米的小圆花坛。甲比乙的总面积大约多少平方米？","given":["甲：1个直径8米的圆","乙：2个直径4米的圆"],"want":"比较两方案总面积的差","relation":"各自求总面积，再比较","formula":"3.14×(8÷2)²−2×3.14×(4÷2)²","steps":["大圆半径4米，面积≈50.24平方米。","每个小圆半径2米，2个总面积≈25.12平方米。","差≈50.24−25.12=25.12平方米。"],"answer":"628/25","answerText":"25.12","unit":"平方米","model":{"type":"compare","mode":"circles","big":"8","small":"4","n":2},"ask":["直径扩大2倍，面积是不是只扩大2倍？","小圆有几个，是否已经算了总面积？"],"change":"先学会这一组的分析方法","id":"c14-0","level":"讲解例题"},{"text":"方案甲建1个直径12米的大圆花坛，方案乙建4个直径6米的小圆花坛。甲比乙的总面积大约多少平方米？","given":["甲：1个直径12米的圆","乙：4个直径6米的圆"],"want":"比较两方案总面积的差","relation":"各自求总面积，再比较","formula":"3.14×(12÷2)²−4×3.14×(6÷2)²","steps":["大圆半径6米，面积≈113.04平方米。","每个小圆半径3米，4个总面积≈113.04平方米。","差≈113.04−113.04=0平方米。"],"answer":"0","answerText":"0","unit":"平方米","model":{"type":"compare","mode":"circles","big":"12","small":"6","n":4},"ask":["直径扩大2倍，面积是不是只扩大2倍？","小圆有几个，是否已经算了总面积？"],"change":"更换数据，数量关系不变","id":"c14-1","level":"基础变式"},{"text":"两根铁丝都长62.8厘米，一根围成正方形，另一根围成圆，接头忽略不计。圆比正方形的面积大约多少平方厘米？","given":["两图形周长都为62.8厘米"],"want":"比较同周长图形的面积","relation":"相同的是周长，分别求面积后相减","formula":"3.14×(62.8÷3.14÷2)²−(62.8÷4)²","steps":["正方形边长=62.8÷4=15.7厘米，面积=246.49平方厘米。","圆半径≈62.8÷3.14÷2=10厘米，面积≈314平方厘米。","面积差≈314−246.49=67.51平方厘米。"],"answer":"6751/100","answerText":"67.51","unit":"平方厘米","model":{"type":"compare","mode":"wire","C":"62.8","r":"10","side":"157/10"},"ask":["铁丝长度不变，保持的是周长还是面积？","圆和正方形需要分别求哪些长度？"],"change":"更换情境或问法，仍从同一关系出发","id":"c14-2","level":"情境变式"},{"text":"把一个圆的半径扩大到原来的3倍，新圆的面积是原来的几倍？","given":["半径变为原来的3倍"],"want":"比较新旧面积的倍数","relation":"面积随半径的平方变化","formula":"3×3","steps":["原面积=π×半径×半径。","两条相乘的半径都变为原来的3倍。","所以面积变为3×3=9倍。"],"answer":"9","answerText":"9","unit":"倍","model":{"type":"compare","mode":"scale","k":3},"ask":["面积公式里半径出现了几次？","半径和面积的变化倍数相同吗？"],"change":"增加条件、逆向设问或提高计算要求","id":"c14-3","level":"进阶变式"}],"priority":false,"extension":false}]};
